steps.script:
var body = tree.root.get_node_or_null("/root/TutorialOverlay/InstructorCard/Margin/VBox/BodyText")
if body == null:
	return "no card"
var t = str(body.text).to_lower().replace("[b]", "").replace("[/b]", "")
if not "attach da warboss to da boyz" in t:
	return "card never names the goal: " + str(body.text)
if not "fight as one" in t:
	return "card never says why: " + str(body.text)
return true

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is OptionButton and nd.item_count > 0 and nd.get_item_text(0) == "(Unattached)":
		nd.select(1)
		nd.item_selected.emit(1)
		return true
	for c in nd.get_children():
		q.append(c)
return false

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is CheckBox and str(nd.text).begins_with("Boyz") and not ("Reserves" in str(nd.text)):
		nd.button_pressed = true
		return true
	for c in nd.get_children():
		q.append(c)
return false

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
var q = [tree.root]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is Button and nd.is_visible_in_tree() and "Re-roll" in str(nd.text):
		nd.pressed.emit()
		return true
	for c in nd.get_children():
		q.append(c)
return true

var bar = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar")
if bar == null:
	return true
var b = bar.get_node_or_null("ContinueButton")
if b == null or not b.is_visible_in_tree():
	b = bar.get_node_or_null("DeployFirstButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var main = tree.current_scene
var dc = main.deployment_controller
var warn = ""
var refused = ""
for t in ToastManager.active_toasts:
	if is_instance_valid(t) and t.get_child_count() > 0:
		var lbl = t.get_child(0)
		if lbl is Label:
			var txt = str(lbl.text)
			if txt.contains("wagon") and txt.contains("Confirm"):
				warn = txt
			if txt.contains("Deployment refused"):
				refused = txt
var tl = main.get_node("BoardRoot/TokenLayer")
var fin = 0
for c in tl.get_children():
	if c.has_meta("unit_id") and str(c.get_meta("unit_id")) == "U_BATTLEWAGON_T":
		fin += 1
var w = GameState.state.units["U_BATTLEWAGON_T"]
var r = "hint=%s dup_toast=%s step=%s placing=%s unit=%s staged=%d/%d previews=%d finalized=%d status=%d pos0=%s confirm=%s card=%s" % [str(warn != ""), str(refused != ""), TutorialManager.current_step_id(), str(dc.is_placing()), dc.unit_id, dc.get_placed_count(), dc.get_total_model_count(), dc.placed_tokens.size(), fin, int(w.status), str(w.models[0].get("position")), str(main.confirm_button.visible), str(main.unit_card.visible)]
print("SCENARIO tut_t2_nudge blocked confirm: " + r)
return r

var wp = InputDeviceManager.get_meta("wp")
var np = tree.current_scene.deployment_controller.temp_positions[0]
return float(wp.distance_to(np))

var TS = load("res://scripts/tutorial/TutorialScript.gd")
var step = {}
for s in TutorialManager._steps:
	if str(s.get("id", "")) == "nudge_wagon":
		step = s
var txt = TS.render_text(str(step.get("prompt", {}).get("pad", "")), true)
return txt.contains("[L3]")

var TS = load("res://scripts/tutorial/TutorialScript.gd")
var step = {}
for s in TutorialManager._steps:
	if str(s.get("id", "")) == "rotate_wagon":
		step = s
var txt = TS.render_text(str(step.get("prompt", {}).get("pad", "")), true)
return txt.contains("[R3]")

var main = tree.current_scene
var tl = main.get_node("BoardRoot/TokenLayer")
var fin = 0
for c in tl.get_children():
	if c.has_meta("unit_id") and str(c.get_meta("unit_id")) == "U_BATTLEWAGON_T":
		fin += 1
var w = GameState.state.units["U_BATTLEWAGON_T"]
return "status=%d tokens=%d previews=%d placing_wagon=%s" % [int(w.status), fin, main.deployment_controller.placed_tokens.size(), str(main.deployment_controller.unit_id == "U_BATTLEWAGON_T")]
